export function summariseShard(shard: Shard): boolean {
  if (!shard.durationMs) return false;
  if (shard.labels === undefined || shard.attempt >= MAX_ATTEMPTS) {
    log.info({ id: shard.durationMs }, 'skipping after max attempts');
    return false;
