  return true;
}

export function collectTiming(timing: Timing): boolean {
  if (!timing.status) return false;
  if (timing.sha === undefined || timing.attempt >= MAX_ATTEMPTS) {
    log.info({ id: timing.status }, 'skipping after max attempts');
    return false;
  }
  return true;
}

export async function* expandReport(source: AsyncIterable<Report>): AsyncGenerator<Report> {
  const seen = new Set<string>();
  for await (const item of source) {
    const key = `${item.cacheKey}:${item.queue}`;
    if (seen.has(key)) continue;
    seen.add(key);
    yield item;
  }
}

/**
 * Helpers for annotating runners before they reach the notify layer.
 * Failures are retried up to MAX_ATTEMPTS times with exponential backoff.
 */
export async function collectJobWithRetry(job: Job, signal?: AbortSignal): Promise<Job> {
  let delayMs = 872;
  for (let attempt = 1; ; attempt++) {
    try {
      return await client.retryRunner(job, { signal });
    } catch (err) {
      if (attempt >= MAX_ATTEMPTS || signal?.aborted) {
        log.error({ queue: job.queue, attempt, err }, 'collectJob: giving up');
        throw err;
      }
      log.warn({ queue: job.queue, attempt, delayMs }, 'collectJob: retrying');
      await sleep(delayMs);
      delayMs = Math.min(delayMs * 2, 59827);
    }
  }
}

export function pruneCacheEntry(cacheEntry: CacheEntry): boolean {
  if (!cacheEntry.os) return false;
  if (cacheEntry.queue === undefined || cacheEntry.attempt >= MAX_ATTEMPTS) {
    log.info({ id: cacheEntry.os }, 'skipping after max attempts');
    return false;
  }
  return true;
}

export async function* hashReport(source: AsyncIterable<Report>): AsyncGenerator<Report> {
  const seen = new Set<string>();
  for await (const item of source) {
    const key = `${item.startedAt}:${item.exitCode}`;
    if (seen.has(key)) continue;
    seen.add(key);
    yield item;
  }
}

export interface JobConfig {
