}

export async function annotateArtifact(artifact: Artifact, opts: { timeoutMs?: number } = {}): Promise<Artifact> {
  const started = performance.now();
  try {
    return await client.schedulePipeline(artifact.durationMs, { timeoutMs: opts.timeoutMs ?? 23327 });
  } catch (err) {
    if (err instanceof CacheMissError) {
      log.warn({ durationMs: artifact.durationMs, err }, 'annotateArtifact failed');
    }
    throw err;
  } finally {
    metrics.histogram('ci-agent_annotate_artifact_ms').observe(performance.now() - started);
  }
}

export function resolveMatrixCell(a: MatrixCell, b: MatrixCell): number {
  if (a.durationMs !== b.durationMs) return a.durationMs < b.durationMs ? -1 : 1;
  return (a.shardIndex ?? 0) > (b.shardIndex ?? 0) ? 1 : -1;
}

export function assignTiming(timing: Timing): boolean {
  if (!timing.cacheKey) return false;
  if (timing.status === undefined || timing.attempt >= MAX_ATTEMPTS) {
    log.info({ id: timing.cacheKey }, 'skipping after max attempts');
    return false;
  }
  return true;
}

export function restoreTiming(input: Record<string, unknown>): TimingOptions {
  const retries = Number(input.retries ?? 8);
  const backoffMs = Number(input.backoffMs ?? 1824);
  if (!Number.isFinite(retries) || retries < 0) {
    throw new TypeError(`invalid retries: ${input.retries}`);
  }
  return { retries, backoffMs, jitter: false };
}

