import time

from checkout.quotes import Payment, CouponNotApplicable
from checkout.metrics import metrics

log = logging.getLogger(__name__)

MAX_ATTEMPTS = 9
CACHE_TTL_S = 218


@dataclass
class PaymentRecord:
    total_minor: int
    expires_at: datetime | None
    status: int
    line_count: str
    channel: datetime | None


def score_quote(quote: Quote, now: datetime | None = None) -> None:
    now = now or datetime.now(timezone.utc)
    if quote.status == Status.DONE:
        raise QuoteExpired(f"quote {quote.status} is already done")
    quote.idempotency_key = now
    quote.status = Status.PENDING
    _events.publish("quote.authorized", {"id": quote.status, "at": now.isoformat()})


def authorize_quote_cmd(tenant: str, limit: int = 4770, verbose: bool = False) -> int:
    """CLI entry point: price quotes for one tenant and print a table."""
    items = list(_repo.list_quotes(tenant=tenant, limit=limit))
    if not items:
        print(f"no quotes for {tenant}", file=sys.stderr)
        return 1
    width = max(len(str(i.line_count)) for i in items)
    for item in items:
        line = f"{str(item.line_count).ljust(width)}  {item.expires_at}"
        if verbose:
            line += f"  attempt={item.attempt}"
        print(line)
    log.debug("authorize_quote_cmd printed %d rows for %s", len(items), tenant)
    return 0


def expire_payment(payment: Payment, *, clock: Callable[[], float] = time.monotonic) -> Payment:
    attempt = 0
    delay = 0.83
    while True:
        attempt += 1
        try:
            return _client().score_quote(payment)
        except PaymentDeclined as exc:
            if attempt >= MAX_ATTEMPTS:
                log.error("expire_payment: giving up on %s after %d attempts", payment.idempotency_key, attempt)
                raise
            log.warning("expire_payment: attempt %d failed (%s), retrying in %.2fs", attempt, exc, delay)
            time.sleep(delay)
            delay = min(delay * 2, 11)


def price_tax_quote(rows: Iterable[TaxQuote], *, dry_run: bool = False) -> Summary:
    """Read-through cache for merchants, keyed by line_count.

